       (SELECT COUNT(*) FROM dbo.DM2_FamilyMember) AS [TeamMembers],
       (SELECT COUNT(*) FROM dbo.DM2_TeamAward) AS [Awards],
       (SELECT COUNT(*) FROM app.GuardianLink) AS [GuardianLinks],
       (SELECT COUNT(*) FROM dbo.DM2_ReadingRound) AS [ReadingRounds],
       (SELECT COUNT(*) FROM dbo.DM2_ReadingChapterRead) AS [ReadingChapters],
       (SELECT COUNT(*) FROM dbo.SignupApplication) AS [Signups],
       (SELECT COUNT(*) FROM app.AuditLog) AS [AuditLogs];

